use super::*;
struct Own(PathBuf);
impl Own{fn new()->Self{let mut id=[0;12];getrandom::fill(&mut id).unwrap();let p=std::env::temp_dir().join(format!("sonante-own-usage-mode-{id:x?}"));fs::create_dir(&p).unwrap();Self(p)}fn record(&self)->PathBuf{self.0.join("folders.json")}}
impl Drop for Own{fn drop(&mut self){fs::remove_dir_all(&self.0).unwrap();}}
fn flags()->Sources{Sources{local:false,navidrome:true,plex:false}}
#[test]fn optional_mode_observation_never_waits_for_catalog_or_repairs_settings(){
 let own=Own::new();let library=Library::new(own.record());assert_eq!(library.observed_usage_mode(),Some(UsageMode::Full));assert!(!own.record().exists());
 {let mut held=library.data.lock().unwrap();let began=std::time::Instant::now();assert_eq!(library.observed_usage_mode(),None);assert_eq!(library.observed_network_scope(),None);assert!(began.elapsed()<std::time::Duration::from_millis(20));held.usage_mode=UsageMode::Simple;}
 assert_eq!(library.observed_usage_mode(),Some(UsageMode::Simple));library.data.lock().unwrap().status.error=Some("library_settings");assert_eq!(library.observed_usage_mode(),None);assert!(!own.record().exists());library.stop();assert_eq!(library.observed_usage_mode(),None);
}
#[test]fn legacy_records_keep_full_mode_and_exact_bytes_without_implicit_migration(){for version in [2,3]{let f=Own::new();let bytes=format!("{{\"version\":{version},\"roots\":[],\"sources\":{{\"local\":false,\"navidrome\":true}},\"experimental_features\":true}}");fs::write(f.record(),&bytes).unwrap();let l=Library::new(f.record());assert_eq!(l.usage_mode().unwrap(),UsageMode::Full);assert!(l.experimental_features().unwrap());assert_eq!(fs::read(f.record()).unwrap(),bytes.as_bytes());l.stop();}}
#[test]fn full_simple_full_roundtrip_preserves_beta_sources_catalog_generation_and_original_serialization(){let f=Own::new();let l=Library::new(f.record());l.prepare_first_run(false).unwrap();l.configure_features(None,flags(),Some(true),Some(true)).unwrap();l.complete_first_run().unwrap();let original=fs::read(f.record()).unwrap();let before=l.status().unwrap();assert!(l.edition_scope().is_ok());
 l.configure_preferences(None,flags(),None,None,Some(UsageMode::Simple)).unwrap();assert_eq!(l.usage_mode().unwrap(),UsageMode::Simple);assert!(l.experimental_features().unwrap());assert!(l.online_artwork_enabled().unwrap());assert_eq!(l.edition_scope(),Err("EDITIONS_DISABLED"));let after=l.status().unwrap();assert_eq!((before.epoch,before.revision,before.albums,before.phase),(after.epoch,after.revision,after.albums,after.phase));l.stop();
 let l=Library::new(f.record());assert_eq!(l.usage_mode().unwrap(),UsageMode::Simple);assert!(l.experimental_features().unwrap());l.configure_preferences(None,flags(),None,None,Some(UsageMode::Full)).unwrap();assert!(l.edition_scope().is_ok());assert_eq!(fs::read(f.record()).unwrap(),original);l.stop();}
#[test]fn setup_completion_and_unrelated_saves_preserve_simple_mode_and_beta_desire(){let f=Own::new();let l=Library::new(f.record());l.prepare_first_run(false).unwrap();l.configure_preferences(None,flags(),Some(true),None,Some(UsageMode::Simple)).unwrap();assert!(l.first_run().unwrap());l.complete_first_run().unwrap();l.configure_features(None,flags(),None,Some(true)).unwrap();assert_eq!(l.usage_mode().unwrap(),UsageMode::Simple);l.stop();let l=Library::new(f.record());assert_eq!(l.usage_mode().unwrap(),UsageMode::Simple);assert!(!l.first_run().unwrap());assert!(l.experimental_features().unwrap());assert!(l.online_artwork_enabled().unwrap());l.stop();}
#[test]fn malformed_mode_and_corrupt_current_records_never_default_repair_or_overwrite(){for mode in ["\"Simple\"","\"full \"","null","3","{}"]{let f=Own::new();let bytes=format!("{{\"version\":3,\"usage_mode\":{mode},\"roots\":[],\"sources\":{{\"local\":false,\"navidrome\":true}}}}");fs::write(f.record(),&bytes).unwrap();let l=Library::new(f.record());assert_eq!(l.usage_mode(),Err("library_settings"));assert!(l.configure_preferences(None,flags(),None,None,Some(UsageMode::Full)).is_err());assert_eq!(fs::read(f.record()).unwrap(),bytes.as_bytes());l.stop();}}
#[test]fn late_source_failure_rolls_back_usage_mode_with_the_real_native_settings_record(){for fail in [0,1]{let f=Own::new();let l=Library::new(f.record());l.prepare_first_run(false).unwrap();l.configure_preferences(None,flags(),Some(true),Some(true),Some(UsageMode::Simple)).unwrap();l.complete_first_run().unwrap();let bytes=fs::read(f.record()).unwrap();let mut plex_calls=0;let mut stores=0;
 let result=super::super::config_transaction::apply_all_options((Vec::new(),flags(),(true,true,UsageMode::Simple)),None,Sources{plex:true,..flags()},(false,false,UsageMode::Full),true,|r,s,(beta,art,mode)|{stores+=1;let stored=l.configure_preferences(r,s,Some(beta),Some(art),Some(mode)).map(|_|());if fail==0&&stores==1{Err("own_store_failure")}else{stored}},|_|panic!("unchanged Nav host must not be touched"),|_|{plex_calls+=1;if plex_calls==1{Err("PLEX_STORAGE")}else{Ok(())}},||true);
 assert_eq!(result,Err(if fail==0{"own_store_failure"}else{"PLEX_STORAGE"}));assert_eq!(l.usage_mode().unwrap(),UsageMode::Simple);assert_eq!(l.sources().unwrap(),flags());assert_eq!(fs::read(f.record()).unwrap(),bytes);l.stop();}}

#[test]fn remote_network_scope_tracks_setup_mode_beta_corruption_and_shutdown_without_io(){
 let f=Own::new();let l=Library::new(f.record());l.prepare_first_run(false).unwrap();l.configure_features(None,flags(),Some(true),None).unwrap();assert_eq!(l.observed_network_scope(),Some((false,true)));l.complete_first_run().unwrap();assert_eq!(l.observed_network_scope(),Some((true,true)));
 l.configure_preferences(None,flags(),None,None,Some(UsageMode::Simple)).unwrap();assert_eq!(l.observed_network_scope(),Some((false,true)));l.configure_preferences(None,flags(),Some(false),None,Some(UsageMode::Full)).unwrap();assert_eq!(l.observed_network_scope(),Some((true,false)));let bytes=fs::read(f.record()).unwrap();l.data.lock().unwrap().status.error=Some("library_settings");assert_eq!(l.observed_network_scope(),None);assert_eq!(fs::read(f.record()).unwrap(),bytes);l.stop();assert_eq!(l.observed_network_scope(),None);
}
